import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"hnl_engine_typecheck_nbe","description":"","frontmatter":{},"headers":[],"relativePath":"api/engine-typecheck-nbe/hnl_engine_typecheck_nbe/index.md","filePath":"api/engine-typecheck-nbe/hnl_engine_typecheck_nbe/index.md"}`),a={name:`api/engine-typecheck-nbe/hnl_engine_typecheck_nbe/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="hnl-engine-typecheck-nbe" tabindex="-1">hnl_engine_typecheck_nbe <a class="header-anchor" href="#hnl-engine-typecheck-nbe" aria-label="Permalink to “hnl_engine_typecheck_nbe”">​</a></h1><h1 id="hnl-engine-typecheck-nbe-1" tabindex="-1">hnl-engine-typecheck-nbe <a class="header-anchor" href="#hnl-engine-typecheck-nbe-1" aria-label="Permalink to “hnl-engine-typecheck-nbe”">​</a></h1><p>A <strong>data-driven, normalization-based typecheck engine</strong> implementing the [<code>TypecheckEngine</code>] trait (ADR-0054 — Generic Typecheck Engine).</p><p>This crate is a <strong>new, minimal, real</strong> engine that proves the ADR-0054 architecture end-to-end. It is <strong>not</strong> a rewrite of the legacy <code>plugin-typecheck-nbe</code> crate; the full rewrite is gated on spikes per the ADR&#39;s Status section.</p><h2 id="architecture-adr-0054-§4" tabindex="-1">Architecture (ADR-0054 §4) <a class="header-anchor" href="#architecture-adr-0054-§4" aria-label="Permalink to “Architecture (ADR-0054 §4)”">​</a></h2><p>The engine:</p><ol><li>Implements [<code>TypecheckEngine</code>].</li><li>Holds a bound [<code>EvalEngine</code>] (for value-level computation in type rules — &quot;types are values&quot;, ADR-0032). The bound eval engine is the pure-eval path: effectful <code>Foreign</code> ops are rejected. For this initial impl, the host constructs the typecheck engine with a pure eval engine; the purity boundary is the host&#39;s responsibility.</li><li>Reads <code>lang.types[node.kind]</code> → [<code>TypeRuleDef</code>] → [<code>Term</code>] (the <code>synth</code> scheme; <code>check</code> is optional) and interprets it.</li><li>Implements the <strong>judgment ops</strong> (ADR-0054 §2) as <code>Arr</code> ops with [<code>ArrSource::Judgment</code>].</li><li>Produces <strong>tagged type values</strong> via the [<code>TypeRegistry</code>] from <code>plugin-lib-tag</code> (ADR-0055): <code>construct</code> mints <code>{&quot;__tag__&quot;:&quot;type.&lt;tag&gt;&quot;,&quot;__registry__&quot;:&quot;handl.canonical&quot;,...}</code>, <code>match_type</code> dispatches on the tag.</li></ol><h2 id="threading-convention" tabindex="-1">Threading convention <a class="header-anchor" href="#threading-convention" aria-label="Permalink to “Threading convention”">​</a></h2><p>[<code>Term::Seq</code>] threads the <code>fst</code> result into <code>snd</code> as the <code>incoming</code> value. The last <code>Seq</code>&#39;s result is the scheme&#39;s result. To recall a previously-computed value, use the <code>bind</code> / <code>result</code> judgment ops:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>synth_child(0) &gt;&gt;&gt; bind(&quot;t&quot;) &gt;&gt;&gt; ... &gt;&gt;&gt; result(&quot;t&quot;)</span></span></code></pre></div><p><code>bind(name)</code> stores <code>incoming</code> under <code>name</code>; <code>result(name)</code> recalls it.</p><h2 id="choice-convention" tabindex="-1">Choice convention <a class="header-anchor" href="#choice-convention" aria-label="Permalink to “Choice convention”">​</a></h2><p>[<code>Term::Choice</code>] routes on an Either value encoded as <code>{&quot;__choice__&quot;: &quot;left&quot;|&quot;right&quot;, &quot;value&quot;: v}</code>. <code>l</code> handles <code>left</code>, <code>r</code> handles <code>right</code>.</p><h2 id="limitations-of-this-initial-impl" tabindex="-1">Limitations of this initial impl <a class="header-anchor" href="#limitations-of-this-initial-impl" aria-label="Permalink to “Limitations of this initial impl”">​</a></h2><ul><li>[<code>Term::Loop</code>] and [<code>Term::App</code>] are not supported (return [<code>LangError::NotImplemented</code>]).</li><li><code>Native</code> <code>Arr</code> ops in type rules are supported only for <code>const</code> and <code>id</code> (trivial, common); other native ops return an engine error. The ADR notes the op set is &quot;refined during implementation&quot;. <code>Foreign</code><code>Arr</code> ops in type rules are <strong>rejected</strong> (ADR-0054 pure-eval path): type rules are static data and must never invoke effectful host calls. The <code>eval_child</code>/<code>proj_child</code> judgment ops additionally perform a static purity check on the child&#39;s AST subtree (gated by the <code>pure</code> flag, default <code>true</code>).</li><li><code>unify</code> uses structural equality, metavariable solving, and recursive structural unification of tagged type values with the same tag from the same registry (ADR-0054 legacy migration); no occurs-check or higher-rank polymorphism. For dependent Pi/Sigma types with <code>body_closure</code> fields, <code>unify</code> skips the closure marker (only unifies <code>param</code>); use the <code>unify_pi</code> judgment op for full closure-based unification (fresh var, apply both, unify bodies).</li><li>Dependent-type closure machinery (<code>construct_pi</code>, <code>construct_sigma</code>, <code>pi_apply</code>, <code>unify_pi</code>, <code>check_pi_body</code>) brings NBE closures into the data-driven engine for Pi/Sigma types (ADR-0054). A Pi/Sigma type value carries a <code>body_closure</code> field recording the variable name and the AST child index of the body; closure application marks Γ, extends it, synths the body child, and restores Γ — mirroring the legacy <code>Closure::apply</code>.</li><li>Forall (parametric polymorphism) and Vau (fexpr) type support (<code>construct_forall</code>, <code>forall_apply</code>, <code>unify_forall</code>, <code>construct_vau_type</code>, <code>vau_apply</code>, <code>unify_vau</code>) extends the closure machinery to <code>type.forall</code> (universal quantification — parameter is a type, field is <code>kind</code>) and <code>type.vau</code> (unevaluated-parameter functions — like <code>type.pi</code> but marked as fexpr). Both reuse the same <code>body_closure</code>/<code>apply_type_closure</code> machinery as Pi/Sigma (ADR-0054).</li><li>Equality type support (<code>construct_eq</code>, <code>construct_empty</code>, <code>check_refl</code>, <code>eq_reduce</code>) brings propositional equality into the data-driven engine (ADR-0054): <code>Eq(a, b)</code> is the equality type (inhabited by <code>Refl</code> iff <code>a == b</code>), <code>Refl</code> is the proof, and <code>Empty</code> is the empty type (contradiction, used when equality fails). These mirror the legacy <code>Value::Eq</code>, <code>Value::Refl</code>, <code>Value::Empty</code>.</li></ul><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="hnl-engine-typecheck-nbe-2" tabindex="-1"><a href="./hnl_engine_typecheck_nbe.html"><code>hnl_engine_typecheck_nbe</code></a> <a class="header-anchor" href="#hnl-engine-typecheck-nbe-2" aria-label="Permalink to “hnl_engine_typecheck_nbe”">​</a></h3><p><em>22 functions, 6 modules, 7 constants, 7 structs</em></p><h3 id="nbetypecheckengine" tabindex="-1"><a href="./NbeTypecheckEngine.html"><code>NbeTypecheckEngine</code></a> <a class="header-anchor" href="#nbetypecheckengine" aria-label="Permalink to “NbeTypecheckEngine”">​</a></h3><p><em>6 functions</em></p><h3 id="typecheckcontext" tabindex="-1"><a href="./TypecheckContext.html"><code>TypecheckContext</code></a> <a class="header-anchor" href="#typecheckcontext" aria-label="Permalink to “TypecheckContext”">​</a></h3><p><em>4 functions</em></p><h3 id="checker" tabindex="-1"><a href="./checker.html"><code>checker</code></a> <a class="header-anchor" href="#checker" aria-label="Permalink to “checker”">​</a></h3><p><em>2 enums, 2 structs, 6 functions</em></p><h3 id="checker-checker" tabindex="-1"><a href="./checker/Checker.html"><code>checker::Checker</code></a> <a class="header-anchor" href="#checker-checker" aria-label="Permalink to “checker::Checker”">​</a></h3><p><em>9 functions</em></p><h3 id="dependent" tabindex="-1"><a href="./dependent.html"><code>dependent</code></a> <a class="header-anchor" href="#dependent" aria-label="Permalink to “dependent”">​</a></h3><p><em>1 static, 1 trait, 6 enums, 7 structs, 8 constants, 91 functions</em></p><h3 id="judgments" tabindex="-1"><a href="./judgments.html"><code>judgments</code></a> <a class="header-anchor" href="#judgments" aria-label="Permalink to “judgments”">​</a></h3><p><em>1 constant, 1 struct, 11 functions</em></p><h3 id="predicate-eval" tabindex="-1"><a href="./predicate_eval.html"><code>predicate_eval</code></a> <a class="header-anchor" href="#predicate-eval" aria-label="Permalink to “predicate_eval”">​</a></h3><p><em>1 enum, 2 type aliases, 26 functions</em></p><h3 id="stats" tabindex="-1"><a href="./stats.html"><code>stats</code></a> <a class="header-anchor" href="#stats" aria-label="Permalink to “stats”">​</a></h3><p><em>1 struct, 16 functions, 35 statics</em></p><h3 id="totality-check" tabindex="-1"><a href="./totality_check.html"><code>totality_check</code></a> <a class="header-anchor" href="#totality-check" aria-label="Permalink to “totality_check”">​</a></h3><p><em>12 functions</em></p>`,36)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};